from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from uuid import UUID
from ..Serializer.PermissionGroup.Permission_Group_Serializer import PermissionGroupSerializer
from ..Serializer.PermissionGroup.Permission_Group_SerializerUnique import PermissionGroupSerializerUnique
from Application.Services.PermissionGroup_Services import PermissionGroup_Services
from Infrastructure.Adapters.Permission_Group_RepositoryI import PermissionGroupRepositoryImpl
from Infrastructure.Adapters.GroupRepositoryI import GroupsRepositoryImpl
from Infrastructure.Adapters.Permission_Level_RepositoryI import PermissionLevelRepositoryImpl
from Infrastructure.Adapters.PermitRepositoryI import PermitRepositoryImpl
from drf_yasg.utils import swagger_auto_schema
from drf_yasg import openapi


class PermissionGroupListController(APIView):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._permission_Group_Service = PermissionGroup_Services(PermissionGroupRepositoryImpl(), GroupsRepositoryImpl(), PermissionLevelRepositoryImpl(), PermitRepositoryImpl())

    @swagger_auto_schema(
        operation_description="Obtiene todos los grupos",
        responses={200: PermissionGroupSerializer(many=True)}
    )
    def get(self, request):
        PermissionGroups = self._permission_Group_Service.list_all()
        serialized_PermissionGroups = PermissionGroupSerializer(PermissionGroups, many=True)
        return Response(serialized_PermissionGroups.data, status=status.HTTP_200_OK)
    
    @swagger_auto_schema(
        request_body=PermissionGroupSerializerUnique,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        operation_description="Crea un nuevo grupo",
        responses={201: PermissionGroupSerializerUnique, 400: "Datos inválidos"}
    )
    def post(self, request):
        serializer = PermissionGroupSerializer(data=request.data)
        if serializer.is_valid():
            PermissionGroup_data = serializer.validated_data
            PermissionGroup = self._permission_Group_Service.create(PermissionGroup_data)
            return Response(PermissionGroupSerializer(PermissionGroup).data, status=status.HTTP_201_CREATED)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)


class PermissionGroupDetailController(APIView):                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._permission_Group_Service = PermissionGroup_Services(PermissionGroupRepositoryImpl(), GroupsRepositoryImpl(), PermissionLevelRepositoryImpl(), PermitRepositoryImpl())

    @swagger_auto_schema(
        operation_description="Obtiene un grupo por ID",
        responses={200: PermissionGroupSerializer(), 404: "grupo no encontrado"}
    )
    def get(self, request, permission_group_id):
        try:
            PermissionGroup = self._permission_Group_Service.get(permission_group_id)
            return Response(PermissionGroupSerializer(PermissionGroup).data, status=status.HTTP_200_OK)
        except Exception as e:
            return Response({'error': str(e)}, status=status.HTTP_404_NOT_FOUND)

    @swagger_auto_schema(
        request_body=PermissionGroupSerializerUnique,
        operation_description="Actualiza un grupo existente",
        responses={200: PermissionGroupSerializerUnique, 400: "Datos inválidos", 404: "grupo no encontrado"}
    )
    def put(self, request, permission_group_id):
        serializer = PermissionGroupSerializerUnique(data=request.data)
        if serializer.is_valid():
            PermissionGroup_data = serializer.validated_data
            try:
                PermissionGroup = self._permission_Group_Service.update(permission_group_id, PermissionGroup_data)
                return Response(PermissionGroupSerializer(PermissionGroup).data, status=status.HTTP_200_OK)
            except Exception as e:
                return Response({'error': str(e)}, status=status.HTTP_404_NOT_FOUND)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

    @swagger_auto_schema(
        operation_description="Elimina un grupo por ID",
        responses={
            204: "grupo eliminado",
            400: "No se pudo eliminar el grupo",
            404: "Grupo no encontrado"
        }
    )
    def delete(self, request, permission_group_id):
        try:                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
            result = self._permission_Group_Service.delete(permission_group_id)
            if result:
                return Response({'message': 'grupo eliminado'}, status=status.HTTP_204_NO_CONTENT)
            return Response({'error': 'No se pudo eliminar el grupo'}, status=status.HTTP_400_BAD_REQUEST)
        except Exception as e:                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
            return Response({'error': str(e)}, status=status.HTTP_404_NOT_FOUND)        